package java.text;
import java.util.Date;import java.util.TimeZone;
public abstract class DateFormat extends Format {public static final int FULL=0,LONG=1,MEDIUM=2,SHORT=3,DEFAULT=MEDIUM;protected TimeZone zone=TimeZone.getDefault();public final String format(Date d){return format(d,new StringBuffer(),new FieldPosition(0)).toString();}public abstract StringBuffer format(Date d,StringBuffer b,FieldPosition p);public StringBuffer format(Object o,StringBuffer b,FieldPosition p){if(o instanceof Date)return format((Date)o,b,p);if(o instanceof Number)return format(new Date(((Number)o).longValue()),b,p);throw new IllegalArgumentException("Cannot format given Object as a Date");}public abstract Date parse(String s,ParsePosition p);public Date parse(String s)throws ParseException{ParsePosition p=new ParsePosition(0);Date d=parse(s,p);if(p.getIndex()==0)throw new ParseException("Unparseable date: \""+s+"\"",p.getErrorIndex());return d;}public Object parseObject(String s,ParsePosition p){return parse(s,p);}public void setTimeZone(TimeZone z){zone=z;}public TimeZone getTimeZone(){return zone;}}
